1	import React from 'react';
2	import loadable from '@loadable/component';
3	import { useLocation } from 'react-router-dom';
4	import { useCategory } from '@salesforce/commerce-sdk-react';
5	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
6	import { HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
7	import Seo from '@salesforce/retail-react-app/app/components/seo';
8	import { Box, Skeleton, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
9	import { categoryIdFromPathSegments, removeSiteLocaleFromPath } from '../../utils/url';
10	
11	const fallback = <Skeleton height="75vh" width="100%" />;
12	
13	// Loadable rather than static imports so this dispatcher stays a small chunk and the PLP and
14	// Experience pages keep the code-split boundaries routes.tsx already gives them.
15	const ProductList = loadable(() => import('../product-list'), { fallback });
16	const Experience = loadable(() => import('../experience'), { fallback });
17	
18	const HTTP_NOT_FOUND = 404;
19	const HTTP_INTERNAL_SERVER_ERROR = 500;
20	
21	/** The path segments of the current page with the site/locale prefix removed. */
22	export const pathSegments = (pathname: string): string[] =>
23	  removeSiteLocaleFromPath(pathname).split('/').filter(Boolean);
24	
25	type CategoryPathProps = {
26	  /** Path segments to resolve; defaults to the current location. Exposed for tests. */
27	  segments?: readonly string[];
28	};
29	
30	/**
31	 * Resolves a hierarchical storefront path (`/clothing/dresses/day-dresses`, SEO PRD DMU-014) to
32	 * the page that owns it. The segments joined with `-` are a category id by construction (see
33	 * `categoryUrlBuilder`), so one category lookup decides: found renders the PLP for that id; not
34	 * found with a single segment renders the Contentful experience page for that slug; anything
35	 * else is a 404. The PLP fetches the same category, and React Query serves it from this lookup.
36	 */
37	const CategoryPath = ({ segments: segmentsProp }: CategoryPathProps) => {
38	  const { pathname } = useLocation();
39	  const segments = segmentsProp ?? pathSegments(pathname);
40	  const categoryId = categoryIdFromPathSegments(segments);
41	  const { res } = useServerContext();
42	  const {
43	    data: category,
44	    isInitialLoading,
45	    error,
46	  } = useCategory({ parameters: { id: categoryId } }, { enabled: segments.length > 0 });
47	
48	  if (category) {
49	    return <ProductList categoryId={categoryId} />;
50	  }
51	
52	  if (isInitialLoading) {
53	    return fallback;
54	  }
55	
56	  // Only a confirmed 404 means "not a category". Any other failure (Commerce API outage, auth)
57	  // is surfaced as an error rather than silently rendering a content page or a false 404 —
58	  // AGENTS.md > Graceful Degradation.
59	  const errorStatus = (error as { response?: { status?: number } } | null)?.response?.status;
60	  if (error && errorStatus !== HTTP_NOT_FOUND) {
61	    const status = errorStatus ?? HTTP_INTERNAL_SERVER_ERROR;
62	    throw new HTTPError(status, `HTTP Error ${status} occurred.`);
63	  }
64	
65	  if (segments.length === 1) {
66	    return <Experience slug={segments[0]} />;
67	  }
68	
69	  if (res) {
70	    res.status(HTTP_NOT_FOUND);
71	  }
72	  return (
73	    <>
74	      <Seo noIndex />
75	      <Box p={8}>
76	        <Text color="red.500">Page not found.</Text>
77	      </Box>
78	    </>
79	  );
80	};
81	
82	CategoryPath.getTemplateName = () => 'category-path';
83	
84	export default CategoryPath;
