/**
 * Returns a stable function that prefixes an internal href with the current site/locale (see
 * `buildSafeHref`) — the single place every internal-navigation call site in this app should
 * reach for, whether that's a JSX `href`/`to` prop, an imperative `history.push()`/
 * `window.location.href`, or a `buildUrl`-style function injected into a hookless utility (e.g.
 * `productListCardMapper.ts`'s `selectProductListCard`, `productInfo.ts`'s `buildRelatedSwatches`).
 *
 * An external/`tel:`/`mailto:`/`#fragment` href is returned unchanged — never run through
 * `buildUrl` (see `buildSafeHref`'s own doc comment for why).
 *
 * @returns a function: `(href: string) => string`
 */
export const useSafeHref = (): ((href: string) => string) => {
  const { buildUrl } = useMultiSite();
  return useCallback((href: string) => buildSafeHref(href, buildUrl), [buildUrl]);
};
