import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';

/**
 * SFCC's own ProductSearchRefinementValue allows any refinement, not just category, to nest
 * child values — flattens the tree into one flat list so a caller (chip-label lookup,
 * checkbox list) sees every nested value, not just the top level.
 */
export const flattenRefinementValues = (
  values: ShopperSearchTypes.ProductSearchRefinementValue[] = [],
): ShopperSearchTypes.ProductSearchRefinementValue[] =>
