  category?: Partial<CategoryLike> & {
    categories?: readonly CategoryLinkItem[];
  };
  onSelect?: () => void;
};

const CategoryLinks = ({ category = {}, onSelect = noop }: CategoryLinksProps) => {
  const { categories = [] } = category;
  // Sub-categories arrive as bare {id, name} records; their tree is the parent's normalised
  // ancestor chain (which appends the parent itself when its tree omits it) plus themselves.
  const parentTree: readonly CategoryPathRecord[] = category.id
    ? categoryAncestorIds({ id: category.id, parentCategoryTree: category.parentCategoryTree }).map((id) => ({ id }))
    : [];
  const childHref = (id: string) => categoryUrlBuilder({ id, parentCategoryTree: [...parentTree, { id }] });

  return (
